"""Writes src/TerraKnight/Player/MountSeats.cs from mount-plan.json: where the rider sits on each mount (Terraria 1.4.5.8)."""
import json
import os

here = os.path.dirname(os.path.abspath(__file__))
plan = json.load(open(os.path.join(here, 'mount-plan.json'), encoding='utf-8'))
out = [
    '// Generated by tools/MountAudit/seats.py from Terraria 1.4.5.8 (Mount.SetAs*/MountData: playerYOffsets, bodyFrame, xOffset,',
    '// yOffset, spawnDust).',
    'namespace TerraKnight.Player {',
    'internal static partial class Mounts {',
    'static readonly System.Collections.Generic.Dictionary<int, MountSeat> seats = new System.Collections.Generic.Dictionary<int, MountSeat> {',
]
for r in plan:
    s = r['stats']
    rise = ','.join(str(v) for v in s['playerYOffsets'])
    out.append('[%d]=new MountSeat(new[]{%s},%d,%d,%d,%d),' % (r['mount'], rise, s['bodyFrame'], s['xOffset'], s['yOffset'], s['spawnDust']))
out += ['};', '}}', '']
path = os.path.join(here, '..', '..', 'src', 'TerraKnight', 'Player', 'MountSeats.cs')
open(path, 'w', encoding='utf-8', newline='\r\n').write('\n'.join(out))
print('wrote', os.path.normpath(path), len(plan))
